const maps = Array.from(ctx.query(world, [WorldMap]));
if (maps.length === 0) {
    return;
}
const mapEid = maps[0];

const agentsWithGridPos = Array.from(ctx.query(world, [Agent, GridPosition]));

const directions = [
    { dx: 0, dy: -1, facing: 'north', animationDirection: 'up' },
    { dx: 0, dy: 1, facing: 'south', animationDirection: 'down' },
    { dx: -1, dy: 0, facing: 'west', animationDirection: 'left' },
    { dx: 1, dy: 0, facing: 'east', animationDirection: 'right' }
];

for (const eid of agentsWithGridPos) {
    const chosenDirection = directions[Math.floor(Math.random() * directions.length)];
    const { dx, dy, facing, animationDirection } = chosenDirection;

    const currentX = GridPosition.x[eid];
    const currentY = GridPosition.y[eid];

    const moved = ctx.grid.moveEntity(world, mapEid, eid, dx, dy);

    if (moved) {
        GridPosition.facing[eid] = facing;

        ctx.emit("movement", {
            entityEid: eid,
            entityName: Name.value[eid],
            fromX: currentX,
            fromY: currentY,
            toX: GridPosition.x[eid],
            toY: GridPosition.y[eid],
            dx: dx,
            dy: dy
        });

        ctx.emit("animation", {
            entityEid: eid,
            entityName: Name.value[eid],
            type: 'walk',
            direction: animationDirection
        });
    }
}
